[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --primary: #1B1464;
      --primary-light: #2D2199;
      --accent: #FFD930;
      --accent-hover: #F5CC00;
      --teal: #0891B2;
      --teal-light: #22D3EE;
      --green: #059669;
      --green-light: #10B981;
      --bg-white: #FFFFFF;
      --bg-light: #F8FAFC;
      --bg-blue: #EFF6FF;
      --text-dark: #0F172A;
      --text-body: #334155;
      --text-muted: #64748B;
      --border: #E2E8F0;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 12px 32px rgba(0,0,0,0.1);
      --shadow-xl: 0 20px 48px rgba(0,0,0,0.12);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;
      --transition: 200ms ease;
      --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }

    html { scroll-behavior: smooth; }

    @media (prefers-reduced-motion: reduce) {
      html { scroll-behavior: auto; }
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }

    body {
      font-family: var(--font);
      color: var(--text-body);
      background: var(--bg-white);
      line-height: 1.6;
      font-size: 16px;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    img { max-width: 100%; display: block; }
    ul { list-style: none; }

    .container {
      width: 100%;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ========== HEADER ========== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      transition: box-shadow var(--transition);
    }

    .header.scrolled {
      box-shadow: var(--shadow-md);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 24px;
      font-weight: 800;
      color: var(--primary);
      cursor: pointer;
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 22px; height: 22px; }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .nav-link {
      padding: 8px 16px;
      font-size: 15px;
      font-weight: 500;
      color: var(--text-body);
      border-radius: var(--radius-sm);
      transition: color var(--transition), background var(--transition);
    }

    .nav-link:hover, .nav-link:focus-visible {
      color: var(--primary);
      background: var(--bg-light);
    }

    .nav-link:focus-visible {
      outline: 2px solid var(--primary);
      outline-offset: 2px;
    }

    .btn-signup {
      padding: 10px 24px;
      font-size: 15px;
      font-weight: 600;
      color: var(--bg-white);
      background: var(--primary);
      border-radius: var(--radius-full);
      transition: background var(--transition), transform var(--transition);
    }

    .btn-signup:hover { background: var(--primary-light); transform: translateY(-1px); }
    .btn-signup:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
    .btn-signup:active { transform: translateY(0); }

    .hamburger {
      display: none;
      width: 44px;
      height: 44px;
      align-items: center;
      justify-content: center;
      border-radius: var(--radius-sm);
      transition: background var(--transition);
    }

    .hamburger:hover { background: var(--bg-light); }
    .hamburger:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }

    .hamburger-icon {
      width: 24px;
      height: 18px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
    }

    .hamburger-icon span {
      display: block;
      width: 100%;
      height: 2px;
      background: var(--text-dark);
      border-radius: 2px;
      transition: transform var(--transition), opacity var(--transition);
    }

    .hamburger.active .hamburger-icon span:nth-child(1) {
      transform: translateY(8px) rotate(45deg);
    }
    .hamburger.active .hamburger-icon span:nth-child(2) {
      opacity: 0;
    }
    .hamburger.active .hamburger-icon span:nth-child(3) {
      transform: translateY(-8px) rotate(-45deg);
    }

    /* Mobile drawer */
    .mobile-drawer {
      position: fixed;
      top: 72px;
      right: 0;
      bottom: 0;
      width: 300px;
      max-width: 85vw;
      background: var(--bg-white);
      box-shadow: var(--shadow-xl);
      transform: translateX(100%);
      transition: transform 250ms ease;
      z-index: 99;
      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .mobile-drawer.open { transform: translateX(0); }

    .mobile-drawer-overlay {
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(0,0,0,0.3);
      z-index: 98;
      opacity: 0;
      pointer-events: none;
      transition: opacity 250ms ease;
    }

    .mobile-drawer-overlay.open { opacity: 1; pointer-events: auto; }

    .mobile-nav-link {
      display: block;
      padding: 14px 16px;
      font-size: 17px;
      font-weight: 500;
      color: var(--text-dark);
      border-radius: var(--radius-sm);
      transition: background var(--transition);
    }

    .mobile-nav-link:hover { background: var(--bg-light); }

    .mobile-drawer .btn-signup {
      display: block;
      text-align: center;
      margin-top: 16px;
    }

    @media (max-width: 768px) {
      .nav-desktop { display: none; }
      .hamburger { display: flex; }
    }

    /* ========== HERO ========== */
    .hero {
      padding: 140px 0 80px;
      background: linear-gradient(170deg, var(--bg-white) 0%, var(--bg-blue) 50%, #DBEAFE 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -200px;
      right: -200px;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(27,20,100,0.04) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -100px;
      left: -100px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(8,145,178,0.05) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero-content {
      text-align: center;
      position: relative;
      z-index: 1;
    }

    .hero h1 {
      font-size: clamp(32px, 5vw, 56px);
      font-weight: 800;
      color: var(--primary);
      line-height: 1.15;
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero-subtitle {
      font-size: clamp(16px, 2vw, 20px);
      color: var(--text-body);
      max-width: 640px;
      margin: 0 auto 48px;
      line-height: 1.7;
    }

    /* ========== SEARCH BAR ========== */
    .search-wrapper {
      max-width: 800px;
      margin: 0 auto;
      position: relative;
      z-index: 10;
    }

    .search-bar {
      display: flex;
      align-items: stretch;
      background: var(--bg-white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      border: 2px solid transparent;
      transition: border-color var(--transition), box-shadow var(--transition);
      overflow: visible;
      position: relative;
    }

    .search-bar:focus-within {
      border-color: var(--primary);
      box-shadow: var(--shadow-xl), 0 0 0 4px rgba(27,20,100,0.08);
    }

    .search-field {
      flex: 1;
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 16px 20px;
      border-right: 1px solid var(--border);
      min-width: 0;
      position: relative;
    }

    .search-field:last-of-type { border-right: none; }

    .search-field svg {
      width: 20px;
      height: 20px;
      color: var(--text-muted);
      flex-shrink: 0;
    }

    .search-field input,
    .search-field select {
      border: none;
      outline: none;
      font-size: 15px;
      font-family: var(--font);
      color: var(--text-dark);
      background: transparent;
      width: 100%;
      min-width: 0;
    }

    .search-field input::placeholder,
    .search-field select { color: var(--text-muted); }

    .search-field select option { color: var(--text-dark); }

    .search-btn {
      padding: 16px 32px;
      background: var(--accent);
      color: var(--primary);
      font-size: 16px;
      font-weight: 700;
      border-radius: 0 var(--radius-md) var(--radius-md) 0;
      transition: background var(--transition), transform var(--transition);
      white-space: nowrap;
      flex-shrink: 0;
    }

    .search-btn:hover { background: var(--accent-hover); }
    .search-btn:focus-visible { outline: 2px solid var(--primary); outline-offset: -2px; }
    .search-btn:active { transform: scale(0.97); }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      right: 0;
      background: var(--bg-white);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-xl);
      border: 1px solid var(--border);
      display: none;
      z-index: 50;
      overflow: hidden;
    }

    .autocomplete-dropdown.visible { display: block; }

    .autocomplete-header {
      padding: 12px 20px 8px;
      font-size: 12px;
      font-weight: 600;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    .autocomplete-item {
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 12px 20px;
      cursor: pointer;
      transition: background var(--transition);
    }

    .autocomplete-item:hover,
    .autocomplete-item.highlighted {
      background: var(--bg-light);
    }

    .autocomplete-item:focus-visible {
      outline: 2px solid var(--primary);
      outline-offset: -2px;
    }

    .autocomplete-icon {
      width: 40px;
      height: 40px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .autocomplete-icon.specialty { background: #EFF6FF; color: var(--primary); }
    .autocomplete-icon.doctor { background: #F0FDF4; color: var(--green); }
    .autocomplete-icon.condition { background: #FEF3C7; color: #D97706; }

    .autocomplete-icon svg { width: 20px; height: 20px; }

    .autocomplete-text { display: flex; flex-direction: column; }
    .autocomplete-name { font-size: 15px; font-weight: 500; color: var(--text-dark); }
    .autocomplete-meta { font-size: 13px; color: var(--text-muted); }

    @media (max-width: 768px) {
      .search-bar {
        flex-direction: column;
        border-radius: var(--radius-md);
      }
      .search-field { border-right: none; border-bottom: 1px solid var(--border); }
      .search-field:last-of-type { border-bottom: none; }
      .search-btn { border-radius: 0 0 var(--radius-md) var(--radius-md); padding: 18px; }
      .hero { padding: 120px 0 60px; }
    }

    /* ========== SPECIALTIES ========== */
    .specialties {
      padding: 96px 0;
      background: var(--bg-white);
    }

    .section-label {
      display: inline-block;
      font-size: 13px;
      font-weight: 600;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 12px;
    }

    .section-title {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      color: var(--primary);
      line-height: 1.2;
      margin-bottom: 16px;
      letter-spacing: -0.02em;
    }

    .section-subtitle {
      font-size: 18px;
      color: var(--text-muted);
      max-width: 560px;
      line-height: 1.6;
    }

    .section-header {
      text-align: center;
      margin-bottom: 56px;
    }

    .section-header .section-subtitle { margin: 0 auto; }

    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .specialty-card {
      display: flex;
      align-items: center;
      gap: 20px;
      padding: 28px;
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
    }

    .specialty-card:hover {
      border-color: var(--primary);
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .specialty-card:focus-visible {
      outline: 2px solid var(--primary);
      outline-offset: 2px;
    }

    .specialty-card:active { transform: translateY(0); }

    .specialty-icon {
      width: 56px;
      height: 56px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .specialty-icon svg { width: 28px; height: 28px; }

    .specialty-icon.blue { background: #EFF6FF; color: var(--primary); }
    .specialty-icon.teal { background: #ECFEFF; color: var(--teal); }
    .specialty-icon.green { background: #F0FDF4; color: var(--green); }
    .specialty-icon.purple { background: #F5F3FF; color: #7C3AED; }
    .specialty-icon.amber { background: #FEF3C7; color: #D97706; }
    .specialty-icon.rose { background: #FFF1F2; color: #E11D48; }

    .specialty-info { min-width: 0; }

    .specialty-name {
      font-size: 17px;
      font-weight: 700;
      color: var(--text-dark);
      margin-bottom: 4px;
    }

    .specialty-desc {
      font-size: 14px;
      color: var(--text-muted);
      line-height: 1.5;
    }

    @media (max-width: 1024px) {
      .specialties-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 600px) {
      .specialties-grid { grid-template-columns: 1fr; gap: 16px; }
      .specialties { padding: 64px 0; }
    }

    /* ========== HOW IT WORKS ========== */
    .how-it-works {
      padding: 96px 0;
      background: var(--bg-light);
    }

    .steps-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 48px;
      position: relative;
    }

    .steps-grid::before {
      content: '';
      position: absolute;
      top: 44px;
      left: calc(16.67% + 24px);
      right: calc(16.67% + 24px);
      height: 2px;
      background: linear-gradient(90deg, var(--teal-light), var(--primary));
      opacity: 0.2;
    }

    .step-card { text-align: center; position: relative; }

    .step-number {
      width: 88px;
      height: 88px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
      color: var(--bg-white);
      font-size: 32px;
      font-weight: 800;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 28px;
      position: relative;
      box-shadow: 0 8px 24px rgba(27,20,100,0.2);
    }

    .step-icon {
      position: absolute;
      bottom: -4px;
      right: -4px;
      width: 36px;
      height: 36px;
      background: var(--accent);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      border: 3px solid var(--bg-light);
    }

    .step-icon svg { width: 16px; height: 16px; color: var(--primary); }

    .step-title {
      font-size: 20px;
      font-weight: 700;
      color: var(--text-dark);
      margin-bottom: 12px;
    }

    .step-desc {
      font-size: 15px;
      color: var(--text-muted);
      max-width: 300px;
      margin: 0 auto;
      line-height: 1.6;
    }

    @media (max-width: 768px) {
      .steps-grid {
        grid-template-columns: 1fr;
        gap: 48px;
      }
      .steps-grid::before { display: none; }
      .how-it-works { padding: 64px 0; }
    }

    /* ========== STATS ========== */
    .stats {
      padding: 64px 0;
      background: var(--primary);
      position: relative;
      overflow: hidden;
    }

    .stats::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 20% 50%, rgba(255,217,48,0.1) 0%, transparent 60%);
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      position: relative;
      z-index: 1;
    }

    .stat-item { text-align: center; }

    .stat-value {
      font-size: clamp(32px, 4vw, 48px);
      font-weight: 800;
      color: var(--accent);
      line-height: 1.1;
      margin-bottom: 8px;
    }

    .stat-label {
      font-size: 15px;
      color: rgba(255,255,255,0.8);
      font-weight: 500;
    }

    @media (max-width: 768px) {
      .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 40px; }
      .stats { padding: 56px 0; }
    }

    @media (max-width: 480px) {
      .stats-grid { grid-template-columns: 1fr; gap: 32px; }
    }

    /* ========== TESTIMONIALS ========== */
    .testimonials {
      padding: 96px 0;
      background: var(--bg-white);
    }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
    }

    .testimonial-card {
      padding: 32px;
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      transition: box-shadow var(--transition), transform var(--transition);
    }

    .testimonial-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .testimonial-stars {
      display: flex;
      gap: 2px;
      margin-bottom: 16px;
    }

    .testimonial-stars svg {
      width: 18px;
      height: 18px;
      color: #FBBF24;
      fill: #FBBF24;
    }

    .testimonial-text {
      font-size: 15px;
      line-height: 1.7;
      color: var(--text-body);
      margin-bottom: 24px;
      font-style: italic;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--teal-light), var(--primary));
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 16px;
      font-weight: 700;
      flex-shrink: 0;
    }

    .testimonial-name {
      font-size: 15px;
      font-weight: 700;
      color: var(--text-dark);
    }

    .testimonial-location {
      font-size: 13px;
      color: var(--text-muted);
    }

    @media (max-width: 1024px) {
      .testimonials-grid { grid-template-columns: 1fr; max-width: 600px; margin: 0 auto; }
    }

    @media (max-width: 600px) {
      .testimonials { padding: 64px 0; }
    }

    /* ========== MOBILE APP PROMO ========== */
    .app-promo {
      padding: 96px 0;
      background: var(--bg-light);
    }

    .app-promo-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .app-promo-content {}

    .app-promo h2 {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      color: var(--primary);
      line-height: 1.2;
      margin-bottom: 16px;
      letter-spacing: -0.02em;
    }

    .app-promo-text {
      font-size: 17px;
      color: var(--text-body);
      margin-bottom: 32px;
      line-height: 1.7;
    }

    .app-features {
      display: flex;
      flex-direction: column;
      gap: 16px;
      margin-bottom: 40px;
    }

    .app-feature {
      display: flex;
      align-items: center;
      gap: 14px;
      font-size: 15px;
      color: var(--text-body);
    }

    .app-feature-icon {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: #ECFDF5;
      color: var(--green);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .app-feature-icon svg { width: 16px; height: 16px; }

    .app-store-buttons {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .store-btn {
      display: inline-flex;
      align-items: center;
      gap: 12px;
      padding: 14px 28px;
      background: var(--primary);
      color: var(--bg-white);
      border-radius: var(--radius-md);
      font-size: 15px;
      font-weight: 600;
      transition: background var(--transition), transform var(--transition);
    }

    .store-btn:hover { background: var(--primary-light); transform: translateY(-1px); }
    .store-btn:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
    .store-btn:active { transform: translateY(0); }
    .store-btn svg { width: 24px; height: 24px; }
    .store-btn-text { display: flex; flex-direction: column; line-height: 1.2; }
    .store-btn-label { font-size: 11px; font-weight: 400; opacity: 0.8; }

    .app-promo-visual {
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .phone-mockup {
      width: 280px;
      height: 560px;
      background: linear-gradient(170deg, var(--bg-blue) 0%, #DBEAFE 100%);
      border-radius: 40px;
      border: 8px solid var(--primary);
      box-shadow: var(--shadow-xl);
      display: flex;
      flex-direction: column;
      align-items: center;
      padding: 48px 24px 32px;
      position: relative;
      overflow: hidden;
    }

    .phone-notch {
      position: absolute;
      top: 12px;
      width: 100px;
      height: 24px;
      background: var(--primary);
      border-radius: 12px;
    }

    .phone-content {
      width: 100%;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .phone-search-bar {
      background: white;
      border-radius: 10px;
      padding: 12px 14px;
      display: flex;
      align-items: center;
      gap: 8px;
      box-shadow: var(--shadow-sm);
    }

    .phone-search-bar svg { width: 16px; height: 16px; color: var(--text-muted); }

    .phone-search-text {
      font-size: 12px;
      color: var(--text-muted);
    }

    .phone-card {
      background: white;
      border-radius: 10px;
      padding: 14px;
      box-shadow: var(--shadow-sm);
    }

    .phone-card-header {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 10px;
    }

    .phone-avatar {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--teal-light), var(--teal));
    }

    .phone-name {
      font-size: 13px;
      font-weight: 600;
      color: var(--text-dark);
    }

    .phone-specialty {
      font-size: 11px;
      color: var(--text-muted);
    }

    .phone-times {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
    }

    .phone-time {
      padding: 6px 10px;
      background: var(--bg-blue);
      border-radius: 6px;
      font-size: 11px;
      font-weight: 600;
      color: var(--primary);
    }

    .phone-time.selected {
      background: var(--primary);
      color: white;
    }

    @media (max-width: 768px) {
      .app-promo-inner {
        grid-template-columns: 1fr;
        gap: 48px;
        text-align: center;
      }
      .app-features { align-items: center; }
      .app-store-buttons { justify-content: center; }
      .app-promo { padding: 64px 0; }
    }

    /* ========== FOOTER ========== */
    .footer {
      padding: 72px 0 32px;
      background: var(--primary);
      color: rgba(255,255,255,0.8);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.5fr repeat(4, 1fr);
      gap: 48px;
      margin-bottom: 56px;
    }

    .footer-brand .logo {
      color: white;
      margin-bottom: 16px;
    }

    .footer-brand .logo-icon { background: var(--accent); }
    .footer-brand .logo-icon svg { color: var(--primary); }

    .footer-tagline {
      font-size: 14px;
      line-height: 1.7;
      opacity: 0.8;
      max-width: 280px;
    }

    .footer-col-title {
      font-size: 14px;
      font-weight: 700;
      color: var(--bg-white);
      text-transform: uppercase;
      letter-spacing: 0.06em;
      margin-bottom: 20px;
    }

    .footer-links { display: flex; flex-direction: column; gap: 12px; }

    .footer-link {
      font-size: 14px;
      color: rgba(255,255,255,0.7);
      transition: color var(--transition);
    }

    .footer-link:hover { color: var(--accent); }
    .footer-link:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 2px; }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 24px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-copyright {
      font-size: 14px;
      opacity: 0.7;
    }

    .footer-legal {
      display: flex;
      gap: 24px;
      flex-wrap: wrap;
    }

    .footer-legal a {
      font-size: 13px;
      color: rgba(255,255,255,0.6);
      transition: color var(--transition);
    }

    .footer-legal a:hover { color: var(--accent); }
    .footer-legal a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 2px; }

    @media (max-width: 1024px) {
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-brand { grid-column: 1 / -1; }
    }

    @media (max-width: 600px) {
      .footer-grid { grid-template-columns: 1fr; gap: 32px; }
      .footer { padding: 48px 0 24px; }
      .footer-bottom { flex-direction: column; text-align: center; }
    }

    /* ========== SCROLL ANIMATIONS ========== */
    .fade-up {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 500ms ease, transform 500ms ease;
    }

    .fade-up.visible {
      opacity: 1;
      transform: translateY(0);
    }

    @media (prefers-reduced-motion: reduce) {
      .fade-up { opacity: 1; transform: none; }
    }

    /* ========== SKIP LINK ========== */
    .skip-link {
      position: absolute;
      top: -100%;
      left: 16px;
      padding: 12px 24px;
      background: var(--primary);
      color: white;
      border-radius: var(--radius-sm);
      font-weight: 600;
      z-index: 200;
      transition: top var(--transition);
    }

    .skip-link:focus {
      top: 16px;
    }
  </style>
</head>
