  <script>
    (function() {
      'use strict';

      // Autocomplete data
      var suggestions = [
        { name: 'Dentist', type: 'specialty', meta: 'Specialty' },
        { name: 'Dermatologist', type: 'specialty', meta: 'Specialty' },
        { name: 'Primary Care', type: 'specialty', meta: 'Specialty' },
        { name: 'Psychiatrist', type: 'specialty', meta: 'Specialty' },
        { name: 'Eye Doctor', type: 'specialty', meta: 'Specialty' },
        { name: 'Orthopedic Surgeon', type: 'specialty', meta: 'Specialty' },
        { name: 'Cardiologist', type: 'specialty', meta: 'Specialty' },
        { name: 'Dr. Sarah Chen', type: 'doctor', meta: 'Dermatologist \u2022 New York, NY' },
        { name: 'Dr. James Wilson', type: 'doctor', meta: 'Primary Care \u2022 Chicago, IL' },
        { name: 'Dr. Maria Santos', type: 'doctor', meta: 'Dentist \u2022 Austin, TX' },
        { name: 'Back pain', type: 'condition', meta: 'Condition' },
        { name: 'Acne', type: 'condition', meta: 'Condition' },
        { name: 'Anxiety', type: 'condition', meta: 'Condition' },
        { name: 'Allergies', type: 'condition', meta: 'Condition' }
      ];

      var searchInput = document.getElementById('search-input');
      var dropdown = document.getElementById('autocomplete-list');
      var highlightedIndex = -1;
      var currentItems = [];

      function getIconSvg(type) {
        if (type === 'specialty') return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>';
        if (type === 'doctor') return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
        return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 8v4M12 16h.01"/></svg>';
      }

      function showSuggestions(query) {
        var filtered = suggestions.filter(function(s) {
          return s.name.toLowerCase().indexOf(query.toLowerCase()) !== -1;
        });

        if (filtered.length === 0 || query.length === 0) {
          dropdown.classList.remove('visible');
          searchInput.setAttribute('aria-expanded', 'false');
          currentItems = [];
          highlightedIndex = -1;
          return;
        }

        currentItems = filtered;
        highlightedIndex = -1;

        var html = '<div class="autocomplete-header">Suggested</div>';
        filtered.forEach(function(item, i) {
          html += '<div class="autocomplete-item" role="option" data-index="' + i + '" id="ac-item-' + i + '">' +
            '<div class="autocomplete-icon ' + item.type + '">' + getIconSvg(item.type) + '</div>' +
            '<div class="autocomplete-text">' +
            '<span class="autocomplete-name">' + highlightMatch(item.name, query) + '</span>' +
            '<span class="autocomplete-meta">' + item.meta + '</span>' +
            '</div></div>';
        });

        dropdown.innerHTML = html;
        dropdown.classList.add('visible');
        searchInput.setAttribute('aria-expanded', 'true');

        dropdown.querySelectorAll('.autocomplete-item').forEach(function(el) {
          el.addEventListener('mousedown', function(e) {
            e.preventDefault();
            searchInput.value = currentItems[parseInt(el.dataset.index)].name;
            dropdown.classList.remove('visible');
            searchInput.setAttribute('aria-expanded', 'false');
          });
        });
      }

      function highlightMatch(text, query) {
        var idx = text.toLowerCase().indexOf(query.toLowerCase());
        if (idx === -1) return text;
        return text.substring(0, idx) + '<strong>' + text.substring(idx, idx + query.length) + '</strong>' + text.substring(idx + query.length);
      }

      function updateHighlight() {
        var items = dropdown.querySelectorAll('.autocomplete-item');
        items.forEach(function(el, i) {
          el.classList.toggle('highlighted', i === highlightedIndex);
        });
        if (highlightedIndex >= 0 && items[highlightedIndex]) {
          searchInput.setAttribute('aria-activedescendant', 'ac-item-' + highlightedIndex);
        } else {
          searchInput.removeAttribute('aria-activedescendant');
        }
      }

      var debounceTimer;
      searchInput.addEventListener('input', function() {
        clearTimeout(debounceTimer);
        debounceTimer = setTimeout(function() {
          showSuggestions(searchInput.value.trim());
        }, 150);
      });

      searchInput.addEventListener('keydown', function(e) {
        if (!dropdown.classList.contains('visible')) return;

        if (e.key === 'ArrowDown') {
          e.preventDefault();
          highlightedIndex = Math.min(highlightedIndex + 1, currentItems.length - 1);
          updateHighlight();
        } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          highlightedIndex = Math.max(highlightedIndex - 1, -1);
          updateHighlight();
        } else if (e.key === 'Enter' && highlightedIndex >= 0) {
          e.preventDefault();
          searchInput.value = currentItems[highlightedIndex].name;
          dropdown.classList.remove('visible');
          searchInput.setAttribute('aria-expanded', 'false');
        } else if (e.key === 'Escape') {
          dropdown.classList.remove('visible');
          searchInput.setAttribute('aria-expanded', 'false');
        }
      });

      searchInput.addEventListener('focus', function() {
        if (searchInput.value.trim().length > 0) {
          showSuggestions(searchInput.value.trim());
        }
      });

      document.addEventListener('click', function(e) {
        if (!e.target.closest('.search-wrapper')) {
          dropdown.classList.remove('visible');
          searchInput.setAttribute('aria-expanded', 'false');
        }
      });

      // Search form
      document.getElementById('search-form').addEventListener('submit', function(e) {
        e.preventDefault();
        dropdown.classList.remove('visible');
      });

      // Mobile menu
      var hamburger = document.getElementById('hamburger-btn');
      var drawer = document.getElementById('mobile-drawer');
      var overlay = document.getElementById('drawer-overlay');
      var drawerLinks = drawer.querySelectorAll('a');

      function openDrawer() {
        drawer.classList.add('open');
        overlay.classList.add('open');
        overlay.setAttribute('aria-hidden', 'false');
        hamburger.classList.add('active');
        hamburger.setAttribute('aria-expanded', 'true');
        hamburger.setAttribute('aria-label', 'Close menu');
        drawerLinks.forEach(function(link) { link.setAttribute('tabindex', '0'); });
      }

      function closeDrawer() {
        drawer.classList.remove('open');
        overlay.classList.remove('open');
        overlay.setAttribute('aria-hidden', 'true');
        hamburger.classList.remove('active');
        hamburger.setAttribute('aria-expanded', 'false');
        hamburger.setAttribute('aria-label', 'Open menu');
        drawerLinks.forEach(function(link) { link.setAttribute('tabindex', '-1'); });
      }

      hamburger.addEventListener('click', function() {
        if (drawer.classList.contains('open')) closeDrawer();
        else openDrawer();
      });

      overlay.addEventListener('click', closeDrawer);

      drawerLinks.forEach(function(link) {
        link.addEventListener('click', closeDrawer);
      });

      document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && drawer.classList.contains('open')) closeDrawer();
      });

      // Header scroll
      var header = document.querySelector('.header');
      var lastScroll = 0;
      window.addEventListener('scroll', function() {
        var scrollTop = window.pageYOffset || document.documentElement.scrollTop;
        header.classList.toggle('scrolled', scrollTop > 10);
        lastScroll = scrollTop;
      }, { passive: true });

      // Scroll animations (IntersectionObserver)
      var fadeEls = document.querySelectorAll('.fade-up');
      if ('IntersectionObserver' in window) {
        var observer = new IntersectionObserver(function(entries) {
          entries.forEach(function(entry) {
            if (entry.isIntersecting) {
              entry.target.classList.add('visible');
              observer.unobserve(entry.target);
            }
          });
        }, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });

        fadeEls.forEach(function(el) { observer.observe(el); });
      } else {
        fadeEls.forEach(function(el) { el.classList.add('visible'); });
      }

      // Stat counter animation
      var statValues = document.querySelectorAll('.stat-value[data-count]');
      if ('IntersectionObserver' in window && statValues.length > 0) {
        var statObserver = new IntersectionObserver(function(entries) {
          entries.forEach(function(entry) {
            if (entry.isIntersecting) {
              animateCount(entry.target);
              statObserver.unobserve(entry.target);
            }
          });
        }, { threshold: 0.5 });

        statValues.forEach(function(el) { statObserver.observe(el); });
      }

      function animateCount(el) {
        var target = parseInt(el.dataset.count, 10);
        var suffix = el.dataset.suffix || '';
        var duration = 1500;
        var start = 0;
        var startTime = null;

        function step(timestamp) {
          if (!startTime) startTime = timestamp;
          var progress = Math.min((timestamp - startTime) / duration, 1);
          var eased = 1 - Math.pow(1 - progress, 3);
          var current = Math.floor(eased * target);

          if (target >= 1000000) {
            el.textContent = (current / 1000000).toFixed(1) + 'M' + suffix;
          } else if (target >= 1000) {
            el.textContent = (current).toLocaleString() + suffix;
          } else {
            el.textContent = current + suffix;
          }

          if (progress < 1) requestAnimationFrame(step);
        }

        requestAnimationFrame(step);
      }
    })();
  </script>
